import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { claimsKey } from '../claims/useClaims';
import { GRADES, peopleKey } from '../people/usePeople';
import { gradesKey, useGrades, type Grade } from './useGrades';

// The sheet's grades, each shown retired or not, and the select and button that retire one (a grade
// already retired is refused). A retired grade cannot be chosen for anyone; people on it keep it.
// A steward merges a grade into another (the same grade twice, or anyone else, is refused): everyone on
// the merged grade today is given the other from the sheet's today, and how many is shown; pressing
// again removes the old count until the new one is in.
export function GradePanel() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const grades = useGrades(sheet);
  const [grade, setGrade] = useState<string>(GRADES[0]);
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const retire = useMutation({
    mutationFn: (chosen: string) =>
      postJson<Grade[]>(`/api/sheets/${encodeURIComponent(sheet)}/grades/retire`, { grade: chosen, user }),
    onSuccess: (saved) => {
      queryClient.setQueryData(gradesKey(sheet), saved);
    },
  });
  const [from, setFrom] = useState<string>(GRADES[0]);
  const [into, setInto] = useState<string>(GRADES[1]);
  const merge = useMutation({
    mutationFn: (chosen: { from: string; into: string }) =>
      postJson<{ merged: number }>(`/api/sheets/${encodeURIComponent(sheet)}/grades/merge`, { ...chosen, user }),
    onSuccess: () =>
      Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
      ]),
  });
  return (
    <>
      <ul data-testid="grade-list">
        {grades.map((g) => (
          <li key={g.grade} data-testid={`grade-row-${g.grade}`}>
            {g.grade} retired: <span data-testid="grade-retired">{g.retired ? 'yes' : 'no'}</span>
          </li>
        ))}
      </ul>
      <select
        data-testid="grade-retire-select"
        value={grade}
        onChange={(e) => {
          setGrade(e.target.value);
          retire.reset();
          merge.reset();
        }}
      >
        {GRADES.map((g) => (
          <option key={g} value={g}>{g}</option>
        ))}
      </select>{' '}
      <button
        type="button"
        data-testid="grade-retire"
        onClick={() =>
          submitOnce(() => {
            retire.reset();
            merge.reset();
            return retire.mutateAsync(grade);
          })
        }
      >
        Retire grade
      </button>
      <p>
        <select
          data-testid="grade-merge-from"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            merge.reset();
            retire.reset();
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>{g}</option>
          ))}
        </select>{' '}
        into{' '}
        <select
          data-testid="grade-merge-into"
          value={into}
          onChange={(e) => {
            setInto(e.target.value);
            merge.reset();
            retire.reset();
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>{g}</option>
          ))}
        </select>{' '}
        <button
          type="button"
          data-testid="grade-merge"
          onClick={() =>
            submitOnce(() => {
              merge.reset();
              retire.reset();
              return merge.mutateAsync({ from, into });
            })
          }
        >
          Merge grade
        </button>
        {merge.isSuccess && (
          <>
            {' '}
            Moved <span data-testid="grade-merged">{merge.data.merged}</span>
          </>
        )}
      </p>
      {retire.isError && <span data-testid="grade-error" role="alert"> The grade could not be retired: it is already retired.</span>}
      {merge.isError && <span data-testid="grade-error" role="alert"> The grade could not be merged.</span>}
    </>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Grade = { grade: string; retired: boolean };

export const gradesKey = (sheet: string) => ['sheet', sheet, 'grades'] as const;

/** The sheet's grades, each with whether it is retired. */
export function useGrades(sheet: string): Grade[] {
  const { data } = useQuery({
    queryKey: gradesKey(sheet),
    queryFn: () => getJson<Grade[]>(`/api/sheets/${encodeURIComponent(sheet)}/grades`),
    enabled: sheet !== '',
  });
  return data ?? [];
}
-- The grades retired on a sheet: a retired grade cannot be chosen for anyone, though people on it keep it.
CREATE TABLE retired_grade (
    sheet_id VARCHAR(200) NOT NULL,
    grade    VARCHAR(20)  NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);
-- A person's grade is dated: each row is a grade in force from its from-date until the next one.
-- A null from-date applies from the beginning of time (the first grade the person was given). A
-- claim uses the grade in force on its date; the list shows the one in force on the sheet's today.
-- One grade per (sheet, person, from-date), a null from-date counting as one value.
CREATE TABLE person_grade (
    seq       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL,
    from_date DATE,
    grade     CHAR(1)      NOT NULL
);
CREATE INDEX person_grade_person ON person_grade (sheet_id, person_id);
INSERT INTO person_grade (sheet_id, person_id, from_date, grade) SELECT sheet_id, id, NULL, grade FROM person;
-- A grade's own terms on a sheet: a claim of a person of that grade (in force on the claim's date) is due this
-- many days after its date. A grade with no row uses the sheet's terms.
CREATE TABLE sheet_grade_terms (
    sheet_id   VARCHAR(200) NOT NULL,
    grade      CHAR(1)      NOT NULL,
    terms_days INT          NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);

-- A claim's due-by, fixed when it is created: its date plus the terms of its person's grade in force on that date.
-- It does not change when the terms or the claim's date change later.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD('DAY', COALESCE((SELECT s.terms_days FROM sheet s WHERE s.id = c.sheet_id), 14), c.claim_date);

