test("grades editable scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-C", "20");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "perm-open", "steward");
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-01");
  expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
  await ui.setSetting(pg_uma, "grace-A", "2");
  expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "7.77"}));
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "pot", "100.00");
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  await ui.setSetting(pg_uma, "review-threshold", "4.00");
  await ui.setSetting(pg_uma, "review-sla", "1");
  await ui.setSetting(pg_uma, "escalate-after", "1");
  await ui.setSetting(pg_uma, "proof-kinds", "receipt");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "5");
  await ui.setSetting(pg_uma, "score-log", "on");
  expect(await ui.addGrade(pg_uma, "D")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00", "from": "2026-03-01"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"})).toBeNull();
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "tags": "a"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "33.33"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "33.33"})).toBe(true);
  expect(await ui.addCrew(pg_uma, "C1", "Ada")).toBe(true);
  expect(await ui.addCrewMember(pg_uma, "C1", "Ben")).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ben, {"terms": ""})).toBe(true);
  expect(await ui.pasteClaims(pg_uma, "Ada,25.00,,\nAda,10.35,2026-03-20,\nAda,99.95,,a, b")).toBeNull();
  const c_ada_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Ada", "amount": "10.25"}, p_ada));
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.addComment(pg_uma, c_ada_0, "see note")).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ben, {"grade": "C", "gradeFrom": "2026-03-28"})).toBe(true);
  expect(await ui.shareClaim(pg_uma, c_ada_0, "Ben", "50.00")).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-settled-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("bulk-settle-batch")).toHaveText("");
  await expect(pg_uma.getByTestId("rollup-cut-total")).toHaveText("100.00");
  await expect(pg_uma.getByTestId("rollup-aged-0-30")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-aged-31-60")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-aged-61")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-people-count")).toHaveText("2");
  await expect(pg_uma.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-REVIEW-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("my-due-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-overdue-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-crew-due-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-reviews-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("watched-due-total")).toHaveText("0.00");
  expect(await ui.setApprover(pg_uma, p_ben, "vic")).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimAction(pg_vic, c_ada_0, "open")).toBe(false);
  expect(await ui.importOpenings(pg_vic, "Ada,P1,x")).toBeNull();
  expect(await ui.addComment(pg_vic, c_ada_0, "see note")).toBe(true);
  expect(await ui.generatePeriods(pg_vic, "2026-01-15", "2026-02-20")).toBe(2);
  expect(await ui.pasteClaims(pg_vic, "Ben,99.95,,\nBen,0.40,2026-02-25,a, b")).toBeNull();
  expect(await ui.ratePreview(pg_vic, "C", "12.50")).toEqual({ count: 0, diff: "0.00" });
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("rollup-overdue-total")).toHaveText("0.00");
